# 과제를 고쳤을 때 버전의 어느 자리를 올리고, 이미 돌린 시도를 어떻게 다루나
AGENT_FACING = {"instruction", "environment", "tools", "agent_resources"}
VERIFIER = {"tests", "judge", "reward"}

def bump(version, changed):
    x, y, z = map(int, version.split("."))
    if changed & AGENT_FACING:
        return f"{x+1}.0.0", "rerun"     # 에이전트가 본 것이 바뀌었다 — 처음부터 다시 돌린다
    if changed & VERIFIER:
        return f"{x}.{y+1}.0", "regrade"  # 궤적·산출물은 그대로, 채점만 다시 한다
    return f"{x}.{y}.{z+1}", "reuse"      # 문서·오라클 해답 — 결과를 그대로 쓴다

for changed in ({"oracle_solution"}, {"tests"}, {"instruction"}, {"docs", "tests"}):
    print(sorted(changed), "→", bump("1.1.0", changed))

# 비용: 445 시도, 시도당 에이전트 비용 $1.80, 채점 비용 $0.02
n, agent_cost, grade_cost = 445, 1.80, 0.02
print(f"rerun ${n * (agent_cost + grade_cost):.0f} vs regrade ${n * grade_cost:.0f}")
